<?php
declare(strict_types=1);

function render_seller_dashboard(): void {
    $u=require_seller();$shop=shop_for_user((int)$u['id']);$pdo=db();$shopId=(int)$shop['id'];
    $counts=[]; foreach(['pending_review','active','draft','rejected','sold'] as $st){$q=$pdo->prepare('SELECT COUNT(*) FROM products WHERE shop_id=? AND status=?');$q->execute([$shopId,$st]);$counts[$st]=(int)$q->fetchColumn();}
    $oq=$pdo->prepare("SELECT o.*, (SELECT COUNT(*) FROM order_items oi WHERE oi.order_id=o.id) AS item_count FROM orders o WHERE o.shop_id=? AND o.status IN ('paid','processing') ORDER BY o.ship_deadline_at ASC LIMIT 5");$oq->execute([$shopId]);$orders=$oq->fetchAll();
    $sales=$pdo->prepare("SELECT COALESCE(SUM(items_total),0) FROM orders WHERE shop_id=? AND paid_at>=DATE_SUB(NOW(),INTERVAL 7 DAY) AND status NOT IN ('cancelled','expired','refunded')");$sales->execute([$shopId]);$sales7=(int)$sales->fetchColumn();
    $wallet=$pdo->prepare('SELECT available_balance,held_balance FROM v_shop_balances WHERE shop_id=?');$wallet->execute([$shopId]);$balances=$wallet->fetch()?:['available_balance'=>0,'held_balance'=>0];
    staff_start('Dashboard','seller','seller_dashboard'); ?>
    <div class="titlebar"><div><h1 class="h1">DASHBOARD</h1><p class="lead"><?=h($shop['name'])?> · <?=h($shop['city'])?></p></div><a class="btn" href="<?=h(route_url('seller_upload'))?>">+ Upload barang</a></div>
    <div class="stats"><div class="stat stat--sky"><span>PESANAN PERLU DIKIRIM</span><b><?=count($orders)?></b><span>Bayar masuk · cek batas kirim</span></div><div class="stat"><span>LISTING AKTIF</span><b><?=$counts['active']?></b><span>Barang di katalog</span></div><div class="stat"><span>MENUNGGU VERIFIKASI</span><b><?=$counts['pending_review']?></b><span>Antrean admin</span></div><div class="stat"><span>PENJUALAN 7 HARI</span><b style="font-size:28px"><?=money($sales7)?></b><span>Nilai barang terbayar</span></div></div>
    <div class="cols"><section class="panel"><div class="panel__h"><h3>Pesanan yang harus dikirim</h3><a class="small footer-link" href="<?=h(route_url('seller_orders'))?>">Lihat semua</a></div><div class="panel__b"><?php if(!$orders): ?><div class="banner-empty">Belum ada pesanan yang menunggu pengiriman.</div><?php else: foreach($orders as $o): ?><div class="section-line" style="padding-top:0"><div class="row between"><b><?=h($o['order_number'])?></b><?=pill($o['status'])?></div><p class="small muted">Batas kirim: <?=h(dt($o['ship_deadline_at']))?> · <?=$o['item_count']?> barang</p><div class="row between" style="margin-top:7px"><b><?=money($o['items_total'])?></b><a class="btn btn--sm" href="<?=h(route_url('seller_orders'))?>">Input resi</a></div></div><?php endforeach; endif; ?></div></section>
    <div><section class="panel"><div class="panel__h"><h3>Status listing</h3><a class="small footer-link" href="<?=h(route_url('seller_products'))?>">Kelola</a></div><div class="panel__b"><div class="sum"><span>Aktif</span><b><?=$counts['active']?></b></div><div class="sum"><span>Draft</span><b><?=$counts['draft']?></b></div><div class="sum"><span>Menunggu verifikasi</span><b><?=$counts['pending_review']?></b></div><div class="sum"><span>Ditolak</span><b><?=$counts['rejected']?></b></div><div class="sum"><span>Terjual</span><b><?=$counts['sold']?></b></div><a class="btn btn--block" style="margin-top:12px" href="<?=h(route_url('seller_products'))?>">Lihat barang saya</a></div></section>
    <section class="panel"><div class="panel__h"><h3>Saldo toko</h3></div><div class="panel__b"><div class="sum"><span>Saldo tersedia</span><b><?=money($balances['available_balance'])?></b></div><div class="sum"><span>Dana ditahan</span><b><?=money($balances['held_balance'])?></b></div><a class="btn btn--ghost btn--block" style="margin-top:12px" href="<?=h(route_url('seller_wallet'))?>">Saldo dan penarikan</a></div></section></div></div>
    <?php staff_end();
}
function render_seller_products(): void {
    $u=require_seller();$shop=shop_for_user((int)$u['id']);$status=trim((string)($_GET['status']??''));$sql='SELECT p.*,(SELECT path FROM product_photos ph WHERE ph.product_id=p.id ORDER BY ph.sort_order,ph.id LIMIT 1) AS main_photo FROM products p WHERE p.shop_id=?';$params=[(int)$shop['id']];if(in_array($status,['draft','pending_review','rejected','active','reserved','sold','inactive'],true)){$sql.=' AND p.status=?';$params[]=$status;}$sql.=' ORDER BY p.updated_at DESC';$q=db()->prepare($sql);$q->execute($params);$items=$q->fetchAll();
    staff_start('Barang saya','seller','seller_products'); ?>
    <div class="titlebar"><div><h1 class="h1">BARANG SAYA</h1><p class="lead">Kelola draft, listing yang menunggu verifikasi, dan status barang.</p></div><a class="btn" href="<?=h(route_url('seller_upload'))?>">+ Upload barang</a></div>
    <div class="chips" style="margin-bottom:16px"><a class="chip <?=$status===''?'is-on':''?>" href="<?=h(route_url('seller_products'))?>">Semua</a><?php foreach(['draft','pending_review','rejected','active','sold'] as $s): ?><a class="chip <?=$status===$s?'is-on':''?>" href="<?=h(route_url('seller_products',['status'=>$s]))?>"><?=h(status_label($s))?></a><?php endforeach; ?></div>
    <div class="panel"><div class="panel__h"><h3>Daftar listing</h3><span class="small muted"><?=count($items)?> barang</span></div><div class="panel__b"><div class="table-scroll"><table class="tbl"><thead><tr><th>Barang</th><th>Harga</th><th>Kondisi</th><th>Status</th><th>Diperbarui</th><th>Aksi</th></tr></thead><tbody><?php if(!$items): ?><tr><td colspan="6">Belum ada barang pada kategori ini.</td></tr><?php else: foreach($items as $p): ?><tr><td><div class="cell"><div class="thumb"><img src="<?=h(product_card_image($p))?>" alt=""></div><div><b><?=h($p['title'])?></b><small>Ukuran <?=h($p['size_label'])?> · #<?=$p['id']?></small></div></div></td><td><?=money($p['price'])?></td><td><?=h($p['condition_score'])?>/10</td><td><?=pill($p['status'])?></td><td><?=h(dt($p['updated_at']))?></td><td><div class="btnrow"><?php if(in_array($p['status'],['draft','rejected','inactive'],true)): ?><a class="btn btn--sm btn--ghost" href="<?=h(route_url('seller_upload',['id'=>$p['id']]))?>">Edit</a><?php endif; ?><a class="btn btn--sm btn--ghost" href="<?=h(route_url('product',['id'=>$p['id']]))?>">Lihat</a></div><?php if($p['status']==='rejected'){$r=db()->prepare('SELECT note,rejection_reason_id FROM verifications WHERE product_id=? ORDER BY created_at DESC LIMIT 1');$r->execute([(int)$p['id']]);$rv=$r->fetch();if($rv):?><small class="neg"><?=h($rv['note']?:'Periksa alasan penolakan dari admin.')?></small><?php endif;} ?></td></tr><?php endforeach; endif; ?></tbody></table></div></div></div>
    <?php staff_end();
}
function render_seller_upload(): void {
    $u=require_seller();$shop=shop_for_user((int)$u['id']);$id=(int)($_GET['id']??0);$p=null;$photos=[];$oldMeasurements=[];$oldDefects=[];
    if($id){$q=db()->prepare('SELECT * FROM products WHERE id=? AND shop_id=?');$q->execute([$id,(int)$shop['id']]);$p=$q->fetch();if(!$p){flash('Produk tidak ditemukan.','bad');redirect('seller_products');}$photos=product_photos($id);$mq=db()->prepare('SELECT measurement_type_id,value_cm FROM product_measurements WHERE product_id=?');$mq->execute([$id]);foreach($mq->fetchAll() as $m)$oldMeasurements[(int)$m['measurement_type_id']]=$m['value_cm'];$dq=db()->prepare('SELECT defect_tag_id FROM product_defects WHERE product_id=?');$dq->execute([$id]);$oldDefects=array_map('intval',$dq->fetchAll(PDO::FETCH_COLUMN));}
    $categories=db()->query('SELECT c.*,COALESCE(c.parent_id,c.id) AS root_id FROM categories c WHERE c.is_active=1 ORDER BY COALESCE(c.parent_id,c.id),c.parent_id IS NOT NULL,c.sort_order')->fetchAll();$brands=db()->query('SELECT * FROM brands ORDER BY name')->fetchAll();$types=db()->query('SELECT * FROM measurement_types ORDER BY id')->fetchAll();$tags=db()->query('SELECT * FROM defect_tags ORDER BY sort_order')->fetchAll();
    $mapQ=db()->query('SELECT category_id,measurement_type_id,is_required FROM category_measurements')->fetchAll();$rootMap=[];foreach($mapQ as $m)$rootMap[(int)$m['category_id']][]=['id'=>(int)$m['measurement_type_id'],'required'=>(int)$m['is_required']];
    staff_start($p?'Edit barang':'Upload barang','seller','seller_upload'); ?>
    <div class="titlebar"><div><h1 class="h1">UPLOAD BARANG</h1><p class="lead">Foto minimal 4, ukuran asli sesuai kategori, dan skor kondisi 6–10.</p></div><a class="btn btn--ghost" href="<?=h(route_url('seller_products'))?>">Kembali ke barang saya</a></div>
    <?php if($p && $p['status']==='rejected'):$rvq=db()->prepare('SELECT v.*,rr.label AS reason_label FROM verifications v LEFT JOIN rejection_reasons rr ON rr.id=v.rejection_reason_id WHERE v.product_id=? ORDER BY v.created_at DESC LIMIT 1');$rvq->execute([$id]);$rv=$rvq->fetch(); ?><div class="notice notice--warn" style="margin-bottom:16px"><div><b>Listing ditolak.</b> <?=h($rv['reason_label']??'Periksa kembali foto dan data listing.')?> <?=h($rv['note']??'')?></div></div><?php endif; ?>
    <form method="post" enctype="multipart/form-data" class="cols" style="grid-template-columns:minmax(0,1.4fr) minmax(280px,1fr)"><?=csrf_field()?><input type="hidden" name="action" value="seller_save_product"><input type="hidden" name="back_route" value="seller_upload"><input type="hidden" name="product_id" value="<?=$id?>">
      <section><div class="panel"><div class="panel__h"><h3>Data barang</h3><span class="small muted">* Wajib diisi</span></div><div class="panel__b"><div class="form form--2"><label class="fld">Judul barang *<input name="title" value="<?=h($p['title']??'')?>" maxlength="150" required placeholder="Contoh: Jaket denim vintage"></label><label class="fld">Kategori *<select name="category_id" id="category-select" required><option value="">Pilih kategori</option><?php foreach($categories as $c): ?><option value="<?=$c['id']?>" data-root="<?=$c['root_id']?>" <?=$p&&(int)$p['category_id']===(int)$c['id']?'selected':''?>><?=($c['parent_id']?'— ':'')?><?=h($c['name'])?></option><?php endforeach; ?></select></label><label class="fld">Merek<select name="brand_id"><option value="0">Tanpa merek</option><?php foreach($brands as $b): ?><option value="<?=$b['id']?>" <?=$p&&(int)$p['brand_id']===(int)$b['id']?'selected':''?>><?=h($b['name'])?></option><?php endforeach; ?></select></label><label class="fld">Bahan<input name="material" value="<?=h($p['material']??'')?>" maxlength="60" placeholder="Katun, denim, rajut"></label><label class="fld">Warna<input name="color" value="<?=h($p['color']??'')?>" maxlength="30" placeholder="Hitam"></label><label class="fld">Gender<select name="gender"><option value="unisex" <?=($p['gender']??'unisex')==='unisex'?'selected':''?>>Unisex</option><option value="male" <?=($p['gender']??'')==='male'?'selected':''?>>Pria</option><option value="female" <?=($p['gender']??'')==='female'?'selected':''?>>Wanita</option></select></label><label class="fld">Jenis ukuran<select name="size_type"><option value="letter" <?=($p['size_type']??'letter')==='letter'?'selected':''?>>Huruf (S, M, L)</option><option value="number" <?=($p['size_type']??'')==='number'?'selected':''?>>Angka (30, 32)</option><option value="shoe" <?=($p['size_type']??'')==='shoe'?'selected':''?>>Sepatu</option><option value="one_size" <?=($p['size_type']??'')==='one_size'?'selected':''?>>One size</option></select></label><label class="fld">Ukuran label *<input name="size_label" value="<?=h($p['size_label']??'')?>" maxlength="10" required placeholder="M / 32 / 41"></label><label class="fld">Harga (Rp) *<input name="price" type="number" min="1" step="1000" value="<?=h($p['price']??'')?>" required></label><label class="fld">Berat (gram) *<input name="weight_gram" type="number" min="1" step="1" value="<?=h($p['weight_gram']??'')?>" required></label></div><label class="fld" style="margin-top:14px">Deskripsi<textarea name="description" maxlength="5000" placeholder="Jelaskan pemakaian, material, dan kondisi secara jujur."><?=h($p['description']??'')?></textarea></label><div class="fld" style="margin-top:16px"><label>Skor kondisi * <small>Skor 1–5 tidak boleh dijual; gunakan 6–10.</small></label><div class="condpick"><?php foreach([10=>'Seperti baru',9=>'Sangat baik',8=>'Baik',7=>'Layak',6=>'Ada kekurangan'] as $sc=>$label): ?><label class="condpick-option"><input style="display:none" type="radio" name="condition_score" value="<?=$sc?>" <?=((int)($p['condition_score']??8)===$sc)?'checked':''?>><span class="<?=((int)($p['condition_score']??8)===$sc)?'is-on':''?>"><b><?=$sc?></b><?=h($label)?></span></label><?php endforeach; ?></div></div></div></div>
      <div class="panel" style="margin-top:18px"><div class="panel__h"><h3>Ukuran asli (cm)</h3><span class="small muted">Diisi sesuai kategori</span></div><div class="panel__b"><div class="form form--2" id="measurements-area"><?php foreach($types as $t):$roots=[];$requiredRoots=[];foreach($rootMap as $r=>$maps)foreach($maps as $map)if($map['id']===(int)$t['id']){$roots[]=$r;if($map['required'])$requiredRoots[]=$r;} ?><label class="fld measurement-field" data-roots="<?=h(implode(',',$roots))?>" data-required-roots="<?=h(implode(',',$requiredRoots))?>"><?=h($t['name'])?> (<?=h($t['unit'])?>)<input type="number" min="0.1" step="0.1" name="measurements[<?=$t['id']?>]" value="<?=h($oldMeasurements[(int)$t['id']]??'')?>" placeholder="cm"></label><?php endforeach; ?></div><p class="small muted" style="margin-top:12px">Ukuran yang ditandai wajib akan diperiksa saat listing dikirim untuk verifikasi.</p></div></div>
      <div class="panel" style="margin-top:18px"><div class="panel__h"><h3>Foto listing</h3><span class="small muted">Minimal 4 foto</span></div><div class="panel__b"><p class="small muted" style="margin-bottom:12px">Pilih foto depan, belakang, label, dan close-up cacat bila ada. Format JPG, PNG, WEBP maksimal 5 MB per foto.</p><div class="form form--2"><?php $photoTypes=['front'=>'Foto depan','back'=>'Foto belakang','label'=>'Foto label','defect'=>'Foto cacat (close-up)','extra'=>'Foto tambahan']; for($i=0;$i<5;$i++): ?><div class="fld"><label><?=$i+1?>. Foto <?= $i<4?'*':'' ?></label><select name="photo_types[]"><?php foreach($photoTypes as $v=>$lab): ?><option value="<?=h($v)?>" <?=array_keys($photoTypes)[$i]===$v?'selected':''?>><?=h($lab)?></option><?php endforeach; ?></select><input type="file" name="photos[]" accept="image/jpeg,image/png,image/webp" <?=$i<4?'':' '?>></div><?php endfor; ?></div><?php if($photos): ?><h4 class="h3" style="margin-top:18px">FOTO TERSIMPAN</h4><div class="gal" style="margin-top:10px"><?php foreach($photos as $ph): ?><div><img src="<?=h(product_photo_url($ph['path']))?>" alt="<?=h($ph['type'])?>"><span><?=h($ph['type'])?></span></div><?php endforeach; ?></div><p class="small muted" style="margin-top:8px">Foto baru akan ditambahkan; foto lama tetap tersimpan.</p><?php endif; ?></div></div>
      </section>
      <aside><div class="panel"><div class="panel__h"><h3>Tag cacat</h3></div><div class="panel__b"><p class="small muted" style="margin-bottom:12px">Pilih kekurangan yang terlihat. Saat mengirim verifikasi, tag cacat perlu memiliki foto close-up.</p><?php foreach($tags as $t): ?><label class="field-check" style="margin:9px 0"><input type="checkbox" name="defect_tags[]" value="<?=$t['id']?>" <?=in_array((int)$t['id'],$oldDefects,true)?'checked':''?>> <?=h($t['name'])?></label><?php endforeach; ?><label class="fld" style="margin-top:14px">Catatan cacat<textarea name="defect_note" placeholder="Contoh: noda kecil di bagian dada."></textarea></label></div></div>
      <div class="panel" style="margin-top:18px"><div class="panel__h"><h3>Sebelum dikirim</h3></div><div class="panel__b"><ul class="list-clean"><li>Minimal empat foto produk.</li><li>Foto label wajib tersedia.</li><li>Ukuran asli wajib diisi sesuai kategori.</li><li>Barang palsu, curian, berbahaya, atau tidak layak pakai dilarang.</li><li>Listing baru tampil setelah disetujui admin.</li></ul><button class="btn btn--block" style="margin-top:12px" type="submit" name="submit_mode" value="submit">Kirim untuk diverifikasi</button><button class="btn btn--ghost btn--block" style="margin-top:8px" type="submit" name="submit_mode" value="draft">Simpan draft</button></div></div></aside>
    </form>
    <script>
    (()=>{const sel=document.getElementById('category-select');const fields=[...document.querySelectorAll('.measurement-field')];const update=()=>{const opt=sel.options[sel.selectedIndex];const root=opt?.dataset.root||'';fields.forEach(el=>{const roots=el.dataset.roots.split(',').filter(Boolean);const req=el.dataset.requiredRoots.split(',').filter(Boolean);el.hidden=!!root&&!roots.includes(root);const input=el.querySelector('input');if(input){input.required=!!root&&req.includes(root);const small=el.querySelector('small');if(small)small.remove();if(input.required){const m=document.createElement('small');m.textContent='Wajib';m.className='muted';el.appendChild(m)}}})};sel?.addEventListener('change',update);update();document.querySelectorAll('.condpick-option input').forEach(i=>i.addEventListener('change',()=>{document.querySelectorAll('.condpick-option span').forEach(s=>s.classList.remove('is-on'));i.nextElementSibling.classList.add('is-on')}));})();
    </script>
    <?php staff_end();
}
function render_seller_orders(): void {
    $u=require_seller();$shop=shop_for_user((int)$u['id']);$q=db()->prepare("SELECT o.*,c.id AS complaint_id,c.status AS complaint_status,c.reason AS complaint_reason,c.decision AS complaint_decision,c.description AS complaint_description,c.buyer_id AS complaint_buyer_id FROM orders o LEFT JOIN complaints c ON c.order_id=o.id WHERE o.shop_id=? AND o.status IN ('paid','processing','shipped','delivered','complained','completed','refunded','cancelled') ORDER BY CASE WHEN o.status IN ('paid','processing') THEN 0 ELSE 1 END,o.created_at DESC");$q->execute([(int)$shop['id']]);$orders=$q->fetchAll();
    staff_start('Pesanan masuk','seller','seller_orders'); ?>
    <div class="titlebar"><div><h1 class="h1">PESANAN MASUK</h1><p class="lead">Kirim sebelum batas waktu 2x24 jam dan simpan nomor resi.</p></div></div>
    <?php if(!$orders): ?><div class="banner-empty">Belum ada pesanan dari pembeli.</div><?php else: foreach($orders as $o):$itq=db()->prepare('SELECT oi.*,p.id AS product_id,(SELECT path FROM product_photos ph WHERE ph.product_id=p.id ORDER BY ph.sort_order,ph.id LIMIT 1) AS photo FROM order_items oi JOIN products p ON p.id=oi.product_id WHERE oi.order_id=?');$itq->execute([(int)$o['id']]);$items=$itq->fetchAll(); ?>
    <div class="panel" style="margin-bottom:18px"><div class="panel__h"><div><b><?=h($o['order_number'])?></b><div class="small muted">Dibuat <?=h(dt($o['created_at']))?></div></div><?=pill($o['status'])?></div><div class="panel__b"><div class="cols cols--eq"><div><?php foreach($items as $it): ?><div class="product-row"><img src="<?=h(product_photo_url($it['photo']))?>" alt="<?=h($it['title_snapshot'])?>"><div><b><?=h($it['title_snapshot'])?></b><p class="small muted">Ukuran <?=h($it['size_snapshot'])?> · <?=money($it['price_snapshot'])?></p></div></div><?php endforeach; ?><div class="sum sum--total"><span>Nilai barang</span><b><?=money($o['items_total'])?></b></div></div><div><div class="kv"><span>Pembeli</span><span><?=h($o['recipient_name'])?></span><span>Alamat tujuan</span><span><?=h($o['address_text'])?></span><span>Kurir</span><span><?=h($o['courier_name'])?></span><span>Batas kirim</span><span><?=h(dt($o['ship_deadline_at']))?></span><span>Nomor resi</span><span><?=h($o['tracking_number']?:'Belum diisi')?></span></div><?php if(in_array($o['status'],['paid','processing'],true)): ?><form method="post" class="form"><?=csrf_field()?><input type="hidden" name="action" value="seller_ship_order"><input type="hidden" name="order_id" value="<?=$o['id']?>"><input type="hidden" name="back_route" value="seller_orders"><label class="fld">Nomor resi<input name="tracking_number" required minlength="5" value="<?=h($o['tracking_number']??'')?>" placeholder="Masukkan nomor resi"></label><button class="btn btn--block" type="submit">Simpan resi & tandai dikirim</button></form><?php endif; ?></div></div>
      <?php if($o['complaint_id']): ?><div class="notice notice--warn" style="margin-top:16px"><div style="width:100%"><b>Komplain · <?=h(status_label($o['complaint_status']))?></b><p><?=h($o['complaint_description'])?></p><?php if($o['complaint_status']!=='resolved'): ?><form method="post" class="stack-form" style="margin-top:12px"><?=csrf_field()?><input type="hidden" name="action" value="seller_reply_complaint"><input type="hidden" name="complaint_id" value="<?=$o['complaint_id']?>"><input type="hidden" name="back_route" value="seller_orders"><label class="fld">Tanggapan penjual<textarea name="seller_response" required minlength="5" placeholder="Jelaskan kondisi barang sebelum dikirim..."></textarea></label><label class="fld">Sikap terhadap komplain<select name="seller_stance" required><option value="agree">Setuju dengan komplain</option><option value="dispute">Tidak setuju / perlu pemeriksaan admin</option></select></label><button class="btn btn--sm" type="submit">Kirim tanggapan</button></form><?php else: ?><p class="small">Keputusan admin: <?=h(status_label($o['complaint_decision']))?></p><?php endif; ?></div></div><?php endif; ?>
    </div></div><?php endforeach; endif; ?>
    <?php staff_end();
}
function render_seller_wallet(): void {
    $u=require_seller();$shop=shop_for_user((int)$u['id']);$pdo=db();$q=$pdo->prepare('SELECT * FROM v_shop_balances WHERE shop_id=?');$q->execute([(int)$shop['id']]);$b=$q->fetch()?:['available_balance'=>0,'held_balance'=>0];$banks=$pdo->prepare('SELECT * FROM bank_accounts WHERE shop_id=? ORDER BY is_default DESC,id DESC');$banks->execute([(int)$shop['id']]);$banks=$banks->fetchAll();$tx=$pdo->prepare('SELECT * FROM wallet_transactions WHERE shop_id=? ORDER BY created_at DESC LIMIT 30');$tx->execute([(int)$shop['id']]);$transactions=$tx->fetchAll();$w=$pdo->prepare('SELECT * FROM withdrawals WHERE shop_id=? ORDER BY created_at DESC LIMIT 20');$w->execute([(int)$shop['id']]);$withdrawals=$w->fetchAll();
    staff_start('Saldo dan penarikan','seller','seller_wallet'); ?>
