    <section class="panel"><div class="panel__h"><h3>Riwayat dana</h3></div><div class="panel__b"><?php if(!$transactions): ?><p class="muted">Belum ada mutasi saldo.</p><?php else: ?><div class="table-scroll"><table class="tbl"><thead><tr><th>Waktu</th><th>Jenis</th><th>Bucket</th><th>Jumlah</th></tr></thead><tbody><?php foreach($transactions as $t): ?><tr><td><?=h(dt($t['created_at']))?><small><?=h($t['note']??'')?></small></td><td><?=h(status_label($t['type']))?></td><td><?=h($t['bucket'])?></td><td class="num"><?=($t['amount']>0?'+':'')?><?=money($t['amount'])?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div></section></div></div>
    <?php staff_end();
