function render_admin_verification(): void {
    require_admin();$pdo=db();$queue=$pdo->query("SELECT p.*,s.name AS shop_name,s.user_id AS seller_id,u.name AS seller_name,c.name AS category_name, (SELECT path FROM product_photos ph WHERE ph.product_id=p.id ORDER BY ph.sort_order,ph.id LIMIT 1) AS main_photo FROM products p JOIN shops s ON s.id=p.shop_id JOIN users u ON u.id=s.user_id JOIN categories c ON c.id=p.category_id WHERE p.status='pending_review' ORDER BY p.submitted_at ASC,p.id ASC")->fetchAll();
    $id=(int)($_GET['id']??($queue[0]['id']??0));$p=null;foreach($queue as $item)if((int)$item['id']===$id)$p=$item;
    $rules=$pdo->query('SELECT * FROM verification_rules WHERE is_active=1 ORDER BY sort_order')->fetchAll();$reasons=$pdo->query('SELECT * FROM rejection_reasons WHERE is_active=1 ORDER BY sort_order')->fetchAll();
    staff_start('Verifikasi listing','admin','admin_verification'); ?>
    <div class="titlebar"><div><h1 class="h1">VERIFIKASI LISTING</h1><p class="lead">Periksa foto, ukuran, cacat, skor kondisi, dan kewajaran listing sebelum tayang.</p></div></div>
    <div class="cols cols--q"><section><div class="row between" style="margin-bottom:10px"><span class="h3">Antrean (<?=count($queue)?>)</span><span class="small muted">Terlama di atas</span></div><div class="qlist"><?php if(!$queue): ?><div class="panel__b">Antrean verifikasi kosong.</div><?php else: foreach($queue as $item): ?><a class="qi <?=$p&&(int)$p['id']===(int)$item['id']?'is-on':''?>" href="<?=h(route_url('admin_verification',['id'=>$item['id']]))?>"><div class="thumb"><img src="<?=h(product_card_image($item))?>" alt=""></div><div><b><?=h($item['title'])?></b><span><?=h($item['seller_name'])?> · <?=h(dt($item['submitted_at'],'d M, H:i'))?></span></div></a><?php endforeach; endif; ?></div></section>
    <?php if($p):$photos=product_photos($id);$mq=$pdo->prepare('SELECT mt.name,pm.value_cm,mt.unit FROM product_measurements pm JOIN measurement_types mt ON mt.id=pm.measurement_type_id WHERE pm.product_id=? ORDER BY mt.id');$mq->execute([$id]);$measures=$mq->fetchAll();$dq=$pdo->prepare('SELECT d.*,t.name,ph.path FROM product_defects d JOIN defect_tags t ON t.id=d.defect_tag_id LEFT JOIN product_photos ph ON ph.id=d.photo_id WHERE d.product_id=?');$dq->execute([$id]);$defs=$dq->fetchAll();$label=false;foreach($photos as $ph)if($ph['type']==='label')$label=true;$defPhotos=0;foreach($defs as $d)if($d['path'])$defPhotos++;$allDef=count($defs)===$defPhotos; ?>
    <section class="panel"><div class="panel__h"><h3><?=h($p['title'])?></h3><?=pill($p['status'])?></div><div class="panel__b"><div class="seller" style="margin-bottom:16px"><span class="ava"><?=h(mb_strtoupper(mb_substr($p['seller_name'],0,1)))?></span><div><b><?=h($p['seller_name'])?></b><div class="small muted"><?=h($p['shop_name'])?> · diajukan <?=h(dt($p['submitted_at']))?></div></div></div>
      <div class="sect" style="margin-top:0"><h4>Foto listing</h4><?php if($photos): ?><div class="gal"><?php foreach($photos as $ph): ?><div><img src="<?=h(product_photo_url($ph['path']))?>" alt="Foto produk"><span><?=h($ph['type'])?></span></div><?php endforeach; ?></div><?php else: ?><p class="muted">Belum ada foto.</p><?php endif; ?></div>
      <div class="sect"><h4>Data listing</h4><div class="kv"><span>Kategori</span><span><?=h($p['category_name'])?></span><span>Harga</span><span><?=money($p['price'])?></span><span>Ukuran label</span><span><?=h($p['size_label'])?></span><span>Ukuran asli</span><span><?php if($measures):foreach($measures as $m)echo h($m['name']).' '.h($m['value_cm']).' '.h($m['unit']).'<br>';else:echo 'Belum diisi';endif;?></span><span>Skor kondisi penjual</span><span><?=h($p['seller_condition_score'])?>/10</span><span>Tag cacat</span><span><?php if($defs):foreach($defs as $d):?><span class="tag"><?=h($d['name'])?></span> <?=h($d['note']??'')?> <br><?php endforeach;else:echo 'Tidak ada tag cacat';endif;?></span></div></div>
      <div class="sect"><h4>Checklist aturan</h4><form method="post" class="stack-form"><?=csrf_field()?><input type="hidden" name="action" value="admin_verify_product"><input type="hidden" name="product_id" value="<?=$id?>"><input type="hidden" name="back_route" value="admin_verification">
      <?php $auto=[1=>count($photos)>=4,2=>$label,3=>$allDef,4=>count($measures)>0,5=>true,6=>false,7=>false];$reasonsText=[1=>'Minimal 4 foto (ada '.count($photos).' foto)',2=>'Foto label terbaca',3=>'Tiap tag cacat punya foto close-up',4=>'Ukuran asli diisi',5=>'Skor kondisi wajar untuk foto yang ada',6=>'Bukan barang terlarang (pakaian dalam bekas, tiruan)',7=>'Harga masuk akal untuk kategori dan kondisi'];foreach($rules as $r):$pass=$auto[(int)$r['id']]??false;?><label class="field-check" style="padding:8px 0;border-bottom:1px solid #d5d5d2"><input type="checkbox" name="checks[<?=$r['id']?>]" value="1" <?=$pass?'checked':''?>> <span style="flex:1"><?=h($r['label'])?></span><span class="pill <?=$pass?'pill--ok':'pill--bad'?>"><?=$pass?'Terpenuhi':'Periksa'?></span></label><?php endforeach; ?>
      <div class="fld"><label>Koreksi skor kondisi</label><select name="adjusted_score"><?php for($s=10;$s>=6;$s--):?><option value="<?=$s?>" <?=$s===(int)$p['seller_condition_score']?'selected':''?>><?=$s?>/10</option><?php endfor;?></select><small>Skor ini akan ditampilkan kepada pembeli jika listing disetujui.</small></div>
      <div class="fld"><label>Alasan penolakan</label><select name="rejection_reason_id"><option value="">Pilih bila ditolak</option><?php foreach($reasons as $r):?><option value="<?=$r['id']?>"><?=h($r['label'])?></option><?php endforeach;?></select></div><label class="fld">Catatan untuk penjual<textarea name="note" placeholder="Tulis alasan atau saran koreksi dengan jelas."></textarea></label>
      <div class="btns"><button class="btn" type="submit" name="decision" value="approved">Setujui listing</button><button class="btn btn--danger" type="submit" name="decision" value="rejected">Tolak dengan alasan</button></div><p class="small muted">Listing harus lolos semua checklist untuk dapat disetujui. Jika ada aturan yang tidak terpenuhi, tolak dengan alasan yang spesifik.</p></form></div>
    </div></section><?php else: ?><section class="panel"><div class="panel__b"><div class="banner-empty">Pilih listing dari antrean untuk memeriksanya.</div></div></section><?php endif; ?></div>
    <?php staff_end();
}
