    <?php if($c):$eq=$pdo->prepare('SELECT ce.*,u.name FROM complaint_evidence ce JOIN users u ON u.id=ce.uploaded_by WHERE ce.complaint_id=? ORDER BY ce.side,ce.created_at');$eq->execute([$id]);$evidence=$eq->fetchAll(); ?>
    <section class="panel"><div class="panel__h"><div><h3>Order #<?=h($c['order_number'])?></h3><div class="small muted">Pembeli: <?=h($c['buyer_name'])?> · Penjual: <?=h($c['seller_name'])?></div></div><?=pill($c['status'])?></div><div class="panel__b"><div class="sect" style="margin-top:0"><h4>RINGKASAN KOMPLAIN</h4><div class="kv"><span>Alasan</span><span><?=h(status_label($c['reason']))?></span><span>Deskripsi</span><span><?=h($c['description'])?></span><span>Batas tanggapan penjual</span><span><?=h(dt($c['seller_deadline_at']))?></span><span>Sikap penjual</span><span><?=h($c['seller_stance']?($c['seller_stance']==='agree'?'Setuju':'Tidak setuju'):'Belum merespons')?></span><span>Tanggapan penjual</span><span><?=h($c['seller_response']?:'Belum ada tanggapan')?></span><span>Nilai pesanan</span><span><?=money($c['total'])?></span></div></div>
      <div class="sect"><h4>BUKTI PEMBELI DAN PENJUAL</h4><?php if($evidence):?><div class="gal"><?php foreach($evidence as $e):?><div><img src="<?=h(product_photo_url($e['path']))?>" alt="Bukti"><span><?=h($e['side'])?> · <?=h($e['caption']?:$e['name'])?></span></div><?php endforeach;?></div><?php else:?><p class="muted">Tidak ada foto bukti terlampir.</p><?php endif;?></div>
      <?php if($c['status']!=='resolved'):?><div class="sect"><h4>KEPUTUSAN ADMIN</h4><form method="post" class="stack-form"><?=csrf_field()?><input type="hidden" name="action" value="admin_decide_complaint"><input type="hidden" name="complaint_id" value="<?=$c['id']?>"><input type="hidden" name="back_route" value="admin_complaints"><label class="fld">Keputusan<select name="decision" id="complaint-decision"><option value="full_refund">Refund penuh</option><option value="partial_refund">Refund sebagian</option><option value="rejected">Komplain ditolak</option></select></label><label class="fld" id="refund-amount-wrap">Jumlah refund sebagian (Rp)<input type="number" name="refund_amount" min="1" max="<?=max(1,(int)$c['seller_net'])?>" step="1000" value="<?=max(1,(int)min(10000,$c['seller_net']))?>"><small>Maksimum nilai bersih penjual <?=money($c['seller_net'])?>.</small></label><label class="fld">Catatan keputusan<textarea name="decision_note" placeholder="Jelaskan alasan keputusan untuk pembeli dan penjual."></textarea></label><button class="btn btn--block" type="submit">Simpan keputusan</button></form></div><script>document.getElementById('complaint-decision')?.addEventListener('change',e=>{document.getElementById('refund-amount-wrap').hidden=e.target.value!=='partial_refund'})</script><?php else:?><div class="notice notice--sky"><div><b>Keputusan:</b> <?=h(status_label($c['decision']))?><br>Refund: <?=money($c['refund_amount']??0)?> · Payout penjual: <?=money($c['seller_payout']??0)?><br><?=h($c['decision_note']??'')?></div></div><?php endif;?></div></section><?php else:?><section class="panel"><div class="panel__b">Pilih komplain dari daftar di sebelah kiri.</div></section><?php endif;?></div>
