    require_admin();$pdo=db();$search=trim((string)($_GET['q']??''));$sql='SELECT * FROM v_user_admin_list';$params=[];if($search!==''){$sql.=' WHERE name LIKE ? OR email LIKE ?';$params=['%'.$search.'%','%'.$search.'%'];}$sql.=' ORDER BY id DESC LIMIT 200';$q=$pdo->prepare($sql);$q->execute($params);$users=$q->fetchAll();
    staff_start('Kelola pengguna','admin','admin_users'); ?>
    <div class="titlebar"><div><h1 class="h1">KELOLA PENGGUNA</h1><p class="lead">Lihat peran, jumlah transaksi, dan catatan negatif. Blokir akun dengan alasan yang jelas.</p></div></div><form method="get" class="searchbar" style="margin-bottom:18px"><input type="hidden" name="r" value="admin_users"><input name="q" value="<?=h($search)?>" placeholder="Cari nama atau email"><button class="btn" type="submit">Cari</button></form><div class="panel"><div class="panel__h"><h3>Daftar pengguna</h3><span class="small muted"><?=count($users)?> akun</span></div><div class="panel__b"><div class="table-scroll"><table class="tbl"><thead><tr><th>Pengguna</th><th>Peran</th><th>Status</th><th>Transaksi</th><th>Catatan negatif</th><th>Aksi</th></tr></thead><tbody><?php foreach($users as $person):?><tr class="<?=$person['status']==='blocked'?'is-blocked':''?>"><td><b><?=h($person['name'])?></b><small><?=h($person['email'])?></small></td><td><?=h($person['role_label'])?></td><td><?=pill($person['status'])?><?php if($person['block_reason']):?><small><?=h($person['block_reason'])?></small><?php endif;?></td><td><?=h($person['transaction_count'])?></td><td><?=h($person['negative_count'])?></td><td><?php if($person['id']!=1):?><form method="post" class="stack-form"><?=csrf_field()?><input type="hidden" name="action" value="admin_toggle_user"><input type="hidden" name="user_id" value="<?=$person['id']?>"><input type="hidden" name="back_route" value="admin_users"><?php if($person['status']==='blocked'):?><input type="hidden" name="mode" value="unblock"><button class="btn btn--sm" type="submit">Buka blokir</button><?php else:?><input type="hidden" name="mode" value="block"><input name="block_reason" required placeholder="Alasan blokir"><button class="btn btn--danger btn--sm" type="submit">Blokir</button><?php endif;?></form><?php else:?><span class="small muted">Admin utama</span><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div></div>
    <?php staff_end();
}
function render_admin_categories(): void {
    require_admin();$pdo=db();$categories=$pdo->query('SELECT c.*,p.name AS parent_name FROM categories c LEFT JOIN categories p ON p.id=c.parent_id ORDER BY COALESCE(c.parent_id,c.id),c.parent_id IS NOT NULL,c.sort_order')->fetchAll();$levels=$pdo->query('SELECT * FROM condition_levels ORDER BY score DESC')->fetchAll();$prohibited=$pdo->query('SELECT * FROM prohibited_items ORDER BY sort_order')->fetchAll();
    staff_start('Kelola kategori','admin','admin_categories'); ?>
    <div class="titlebar"><div><h1 class="h1">KELOLA KATEGORI</h1><p class="lead">Kategori, skala kondisi, dan daftar barang yang tidak boleh dijual.</p></div></div><div class="cols cols--eq"><section class="panel"><div class="panel__h"><h3>Daftar kategori</h3></div><div class="panel__b"><div class="table-scroll"><table class="tbl"><thead><tr><th>Nama</th><th>Slug</th><th>Status</th><th>Jenis</th></tr></thead><tbody><?php foreach($categories as $c):?><tr><td><?=($c['parent_id']?'— ':'')?><?=h($c['name'])?> <?=$c['is_new']?'<span class="badge-count">BARU</span>':''?></td><td><?=h($c['slug'])?></td><td><?= $c['is_active']?'<span class="pill pill--ok">Aktif</span>':'<span class="pill pill--mute">Nonaktif</span>'?></td><td><?=h($c['parent_name']?'Subkategori':'Kategori utama')?></td></tr><?php endforeach;?></tbody></table></div>
      <h3 class="h3" style="margin:22px 0 12px">TAMBAH KATEGORI</h3><form method="post" class="stack-form"><?=csrf_field()?><input type="hidden" name="action" value="admin_add_category"><input type="hidden" name="back_route" value="admin_categories"><label class="fld">Nama kategori<input name="name" required maxlength="60"></label><label class="fld">Kategori induk<select name="parent_id"><option value="0">Kategori utama</option><?php foreach($categories as $c):if(!$c['parent_id']):?><option value="<?=$c['id']?>"><?=h($c['name'])?></option><?php endif;endforeach;?></select></label><button class="btn" type="submit">Tambah kategori</button></form></div></section>
    <div><section class="panel"><div class="panel__h"><h3>Skala kondisi 1–10</h3></div><div class="panel__b"><div class="table-scroll"><table class="tbl"><thead><tr><th>Skor</th><th>Nama</th><th>Dapat dijual</th></tr></thead><tbody><?php foreach($levels as $l):?><tr><td><b><?=h($l['score'])?>/10</b></td><td><?=h($l['name'])?><small><?=h($l['description'])?></small></td><td><?=$l['is_sellable']?'<span class="pill pill--ok">Ya</span>':'<span class="pill pill--bad">Tidak</span>'?></td></tr><?php endforeach;?></tbody></table></div></div></section>
      <section class="panel" style="margin-top:18px"><div class="panel__h"><h3>Barang yang dilarang dijual</h3></div><div class="panel__b"><ul class="item-list"><?php foreach($prohibited as $item):?><li><?=h($item['name'])?></li><?php endforeach;?></ul><form method="post" class="form"><?=csrf_field()?><input type="hidden" name="action" value="admin_add_prohibited"><input type="hidden" name="back_route" value="admin_categories"><label class="fld">Tambah larangan baru<input name="name" required maxlength="150" placeholder="Jenis barang yang dilarang"></label><button class="btn btn--ghost btn--block" type="submit">Tambahkan</button></form></div></section></div></div>
    <?php staff_end();
}
function render_admin_withdrawals(): void {
    require_admin();$pdo=db();$items=$pdo->query("SELECT w.*,s.name AS shop_name,u.name AS seller_name FROM withdrawals w JOIN shops s ON s.id=w.shop_id JOIN users u ON u.id=s.user_id ORDER BY (w.status='requested') DESC,w.created_at DESC LIMIT 300")->fetchAll();
    staff_start('Penarikan penjual','admin','admin_withdrawals'); ?>
    <div class="titlebar"><div><h1 class="h1">PENARIKAN PENJUAL</h1><p class="lead">Kelola permintaan penarikan saldo. Dalam mode demo, pembayaran ke rekening tetap dilakukan manual di luar aplikasi.</p></div></div><div class="panel"><div class="panel__h"><h3>Permintaan penarikan</h3><span class="small muted"><?=count($items)?> data</span></div><div class="panel__b"><div class="table-scroll"><table class="tbl"><thead><tr><th>Toko / Penjual</th><th>Rekening</th><th>Jumlah</th><th>Status</th><th>Aksi admin</th></tr></thead><tbody><?php if(!$items):?><tr><td colspan="5">Belum ada permintaan penarikan.</td></tr><?php else:foreach($items as $w):?><tr><td><b><?=h($w['shop_name'])?></b><small><?=h($w['seller_name'])?> · <?=h(dt($w['created_at']))?></small></td><td><?=h($w['bank_name'])?><small><?=h($w['account_number'])?> · <?=h($w['account_holder'])?></small></td><td><?=money($w['amount'])?></td><td><?=pill($w['status'])?><?php if($w['reject_reason']):?><small><?=h($w['reject_reason'])?></small><?php endif;?></td><td><?php if(in_array($w['status'],['requested','processing'],true)):?><form method="post" class="stack-form"><?=csrf_field()?><input type="hidden" name="action" value="admin_process_withdrawal"><input type="hidden" name="withdrawal_id" value="<?=$w['id']?>"><input type="hidden" name="back_route" value="admin_withdrawals"><select name="decision"><option value="processing">Tandai diproses</option><option value="completed">Tandai selesai</option><option value="rejected">Tolak</option></select><input name="reject_reason" placeholder="Alasan jika ditolak"><button class="btn btn--sm" type="submit">Simpan</button></form><?php else:?><span class="small muted">Sudah diproses</span><?php endif;?></td></tr><?php endforeach;endif;?></tbody></table></div></div></div>
    <?php staff_end();
}
